INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 26, 'theory', 'Quiz: text and formatting');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 0, 'What does "k=v".split_once(''='') do?', '["returns an iterator with two elements", "splits at the first occurrence and returns Option<(&str, &str)>", "returns a pair of String", "panics if there is no sign"]', 1, 'split_once is handy for parsing «key=value»; if there is no separator it returns None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 1, 'What does the specifier {:>8.2} mean?', '["left alignment, 8 digits", "width 2, precision 8", "right alignment in a field of width 8, two digits after the decimal point", "output in hexadecimal"]', 2, '> is right, 8 is the width, .2 is the precision for floating-point numbers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 2, 'How does Display differ from Debug?', '["no difference", "Debug works only for numbers", "Display cannot be used with println!", "Display is for the user ({}), written by hand; Debug is for the programmer ({:?}), usually via derive"]', 3, 'Two different traits: nice output for people and debug output for developers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 3, 'What will "0x1f".parse::<i32>() return?', '["Err: parse does not understand the 0x prefix", "Ok(31)", "Ok(0)", "a panic"]', 0, 'You have to strip the prefix and call i32::from_str_radix("1f", 16).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 4, 'What do split, trim_matches and find accept as a pattern?', '["only &str", "only char", "char, &str, an array of chars, or a closure returning bool", "only regular expressions"]', 2, 'The Pattern trait is implemented for all these types — you do not need regexes for simple tasks.');
